import{_ as l,a0 as i,w as d,s as r,ao as o,I as t,x as s,a1 as p,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"编写一个简单的游戏来学习 Python | LCTT x X-CMD","titleTemplate":false,"description":"编写一个简单的游戏来学习 Python | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"编写一个简单的游戏来学习 Python | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"编写一个简单的游戏来学习 Python | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20201228 Learn Python by coding a simple game","title":"编写一个简单的游戏来学习 Python","tag":"202101","desc":""},"relativePath":"202101/20201228 Learn Python by coding a simple game.md","filePath":"[post].md"}'),h={name:"202101/20201228 Learn Python by coding a simple game.md"};function u(m,n,g,c,y,T){const a=i("Link");return d(),r("div",null,[n[18]||(n[18]=o('<h1 id="编写一个简单的游戏来学习-python" tabindex="-1">编写一个简单的游戏来学习 Python <a class="header-anchor" href="#编写一个简单的游戏来学习-python" aria-label="Permalink to “编写一个简单的游戏来学习 Python”">​</a></h1><blockquote><p>通过编写一个“猜数字”游戏来探索 Python（和其他编程语言）。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202101/01/105156uwwgx3tw2otntoow.jpg" alt=""></p><p>在这个系列中，我们要用不同的编程语言编写相同的应用，以比较各种语言是如何工作的，并说明使用标准测试程序是学习新编程好方法。</p><p>当你学习一门新的编程语言时，关注它们的共同点是件好事。变量、表达式和语句是大多数编程语言的基础。一旦你理解了这些概念，你就可以开始弄清楚其余的东西。</p><p>因为编程语言有许多相似之处，一旦你知道一种语言，你通常可以通过观察它与你所知道的语言的不同之处来学习另一种语言的基础知识。使用你用其他语言编写的标准测试程序，可以让你专注于语言，而不是程序的逻辑。</p><p>为了证明这点，我们正在测试如何用多种语言编写一个“猜数字”程序。计算机选择一个 1 到 100 之间的数字，然后让你猜。程序循环，直到你猜出正确答案。</p><p>“猜数字”程序练习了编程语言的几个概念：</p><ul><li>变量</li><li>输入</li><li>输出</li><li>条件判断</li><li>循环</li></ul><p>这是一个很好的学习新编程语言的实践实验。</p><h3 id="用-python-猜数字" tabindex="-1">用 Python 猜数字 <a class="header-anchor" href="#用-python-猜数字" aria-label="Permalink to “用 Python 猜数字”">​</a></h3>',11)),t("p",null,[n[1]||(n[1]=s("用 ",-1)),p(a,{href:"https://docs.python.org/3/faq/general.html#general-information"},{default:e(()=>[...n[0]||(n[0]=[s("Python 软件基金会",-1)])]),_:1}),n[2]||(n[2]=s("的话来说。“Python 是一种解释性的、交互式的、面向对象的程序设计语言，它包含了模块、异常、动态类型、非常高层的动态数据类型和类。”它是一种很好的通用编程语言，从简单的脚本到复杂的 GUI 应用都很适用。",-1))]),n[19]||(n[19]=o(`<p>你可以通过编写一个版本的“猜数字”游戏来探索 Python。这是我的实现：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import random as randomlib</span></span>
<span class="line"><span>random = randomlib.randint(1, 100)</span></span>
<span class="line"><span>print(&quot;Guess a number between 1 and 100&quot;)</span></span>
<span class="line"><span>while True:</span></span>
<span class="line"><span>    guess = int(input())</span></span>
<span class="line"><span>    if guess &amp;lt; random:</span></span>
<span class="line"><span>        print(&quot;Too low&quot;)</span></span>
<span class="line"><span>    elif guess &amp;gt; random:</span></span>
<span class="line"><span>        print(&quot;Too high&quot;)</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        print(&quot;That&#39;s right!&quot;)</span></span>
<span class="line"><span>        break</span></span></code></pre></div><p>要给一个变量赋值，请列出变量的名称，然后是 <code>=</code> 号。例如，语句 <code>random = 0</code> 给 <code>random</code> 变量分配了一个零值。</p><p>脚本的第一行就导入了 <code>random</code> 模块。由于本系列中的所有程序都使用 <code>random</code> 作为变量的名称，你可以使用 <code>import random as randomlib</code> 以别名导入它，以避免命名冲突。</p><p>很少有函数被内置到 Python 中，大多数函数必须从标准库中显式导入。<code>random</code> 标准库模块有生成各种随机值的功能。</p><p>脚本的第二行读取函数 <code>randint()</code> 的结果，并将其赋值给名为 <code>random</code> 的变量。函数需要两个参数：一个最小值和一个最大值。在本例中，范围是 <code>1</code> 到 <code>100</code>，以使游戏具有足够的挑战性。</p><p>你可以使用 <code>input()</code> 函数提示用户输入一个值。如果你写 <code>guess = int(input())</code>，Python 会等待用户输入一些文本，将其转换为一个整数，然后将值存储在 <code>guess</code> 变量中。</p><p>Python 支持条件表达式和循环等流程控制。在“猜数字”游戏中，只要 <code>guess</code> 中的值不等于 <code>random</code>，Python 就会继续循环。</p><p>如果猜测值小于随机数，Python 会打印 <code>Too low</code>，如果猜测值大于这个数字，Python 会打印 <code>Too high</code>。</p><h3 id="示例输出" tabindex="-1">示例输出 <a class="header-anchor" href="#示例输出" aria-label="Permalink to “示例输出”">​</a></h3><p>现在你已经写好了 Python 程序，运行它来玩“猜数字”游戏。每次运行程序，Python 都会随机选取一个不同的数字。为了完成这个游戏，你需要猜测，直到找到正确的数字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python guess.py</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span> 50</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span> 25</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span> 12</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span> 7</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span> 3</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span> 5</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span> 6</span></span>
<span class="line"><span>That&#39;s right!</span></span></code></pre></div><p>在学习一门新的编程语言时，这个“猜数字”游戏是一个很好的入门程序，因为它以一种相当直接的方式练习了几个常见的编程概念。通过在不同的编程语言中实现这个简单的游戏，你可以展示不同编程语言的一些核心概念，并比较每种语言的细节。</p><p>你有喜欢的编程语言吗？你会如何编写“猜数字”游戏？请关注本系列文章，看看你可能感兴趣的其他编程语言的例子吧！</p><hr>`,15)),t("p",null,[n[4]||(n[4]=s("via: ",-1)),p(a,{href:"https://opensource.com/article/20/12/learn-python"},{default:e(()=>[...n[3]||(n[3]=[s("https://opensource.com/article/20/12/learn-python",-1)])]),_:1})]),t("p",null,[n[9]||(n[9]=s("作者：",-1)),p(a,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...n[5]||(n[5]=[s("Moshe Zadka",-1)])]),_:1}),n[10]||(n[10]=s(" 选题：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...n[6]||(n[6]=[s("lujun9972",-1)])]),_:1}),n[11]||(n[11]=s(" 译者：",-1)),p(a,{href:"https://github.com/geekpi"},{default:e(()=>[...n[7]||(n[7]=[s("geekpi",-1)])]),_:1}),n[12]||(n[12]=s(" 校对：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[8]||(n[8]=[s("wxy",-1)])]),_:1})]),t("p",null,[n[15]||(n[15]=s("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[13]||(n[13]=[s("LCTT",-1)])]),_:1}),n[16]||(n[16]=s(" 原创编译，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...n[14]||(n[14]=[s("Linux中国",-1)])]),_:1}),n[17]||(n[17]=s(" 荣誉推出",-1))])])}const k=l(h,[["render",u]]);export{P as __pageData,k as default};
